/**
 * dsh-mcp-manager — 客户端右上角浮窗。
 *
 * 浮窗胶囊（状态点 + 摘要计数）挂在会话滚动容器右上角，点击展开下拉面板
 * 展示项目/全局 MCP 服务器列表 + 快捷操作（连接/断开/禁用）。
 * 跨模块动作（showPanel / refresh）经 actions 注入，不直接引用 panel 模块。
 */

import { el, pangu } from "../core/dom.ts";
import { api, toolDisableServerKey, cwdQueryOf } from "../core/api.ts";
import { STATUS_ORDER, statusDot } from "../core/constants.ts";
import { tStatus } from "../core/i18n.ts";
import { t } from "../../../../../shared/client/i18n.js";
import { readCurrentSession } from "../core/current-session.ts";
import type { McpClientContext, McpServerListEntry, McpState, UiActions } from "../core/state.ts";
import type { ClientUiConfig, FloatBreakpoint, ViewportPoint } from "../../shared/interface.ts";
import {
  DEFAULT_Z_INDEX_BASE,
  breakpointForWidth,
  clampPointToViewport,
  clampZIndexBase,
  panelAnchorForPosition,
  composerDockedAtBottom,
  bottomAnchorEdge,
} from "../../shared/interface.ts";

/** 重播 CSS animation：强制 reflow 后再挂 class。 */
function replayAnim(node: Element): void {
  const style = (node as HTMLElement).style;
  style.animation = "none";
  void (node as HTMLElement).offsetWidth;
  style.animation = "";
}

/** 胶囊状态点配色：失败红 / 有连接绿 / 否则中性灰（与历史三态一致）。 */
export function pillDotColor(fail: boolean, connected: number): string {
  if (fail) return "var(--dsw-alias-state-error-primary,#e0483e)";
  if (connected > 0) return "var(--dsw-alias-state-success-primary,#0f9d6e)";
  return "var(--dsw-alias-label-tertiary,#9aa1ad)";
}

/**
 * 胶囊的 title / aria-label：一台服务器都没有时不设（保留宿主默认 tooltip），
 * 有失败时追加失败计数，否则 aria 给出「已连/总数」（无总数时 title 保持朴素）。
 */
export function pillHints(
  total: number,
  bad: number,
  connected: number,
): { title: string; aria: string } {
  const failed = t("healthFailed", { n: bad });
  return {
    title: bad > 0 ? `${t("floatTitle")} · ${failed}` : t("floatTitle"),
    aria:
      bad > 0
        ? `${t("floatAriaLabel")} · ${failed}`
        : `${t("floatAriaLabel")} · ${connected}/${total}`,
  };
}

/** 渲染浮窗胶囊（状态点 + 摘要计数 + 失败/中性态）。 */
export function renderPill(state: McpState): void {
  if (state.floatPill === undefined) return;
  const ok = state.counts.connected ?? 0;
  const bad = (state.counts.failed ?? 0) + (state.counts.reconnecting ?? 0);
  const total = state.servers.length;
  const fail = bad > 0;
  state.floatPill.classList.toggle("dm-float--fail", fail);
  state.floatPill.textContent = "";
  state.floatPill.appendChild(
    el("span", { class: "dm-dot", style: `background:${pillDotColor(fail, ok)}` }),
  );
  if (fail) state.floatPill.appendChild(el("span", { class: "dm-float-fail", text: "!" }));
  state.floatPill.appendChild(el("span", { text: total > 0 ? `MCP ${ok}/${total}` : "MCP" }));
  if (total === 0) return;
  const hints = pillHints(total, bad, ok);
  state.floatPill.title = hints.title;
  state.floatPill.setAttribute("aria-label", hints.aria);
}

/**
 * 工具级禁用开关（PATCH /api/dsh-mcp/tool-disable）。
 * 语义（#362 交互拍板 2b）：折叠式 details 展开后 checkbox 列表，逐个启停；
 * 点击调宿主 API 持久化 + 刷新。单池（#767）后全部服务器（含全局）都经中间层，
 * 项目组与全局组一律渲染 checkbox。
 */
function toolCheckbox(
  server: McpServerListEntry,
  tool: string,
  disabled: boolean,
  state: McpState,
  actions: UiActions,
): HTMLElement {
  const label = el("label", { class: "dm-float-tool" });
  const input = el("input", {
    type: "checkbox",
    checked: disabled,
    dataset: { dshMcpTool: tool },
  });
  input.addEventListener("change", () => {
    // C6：全名形态经 toolDisableServerKey 归一（@@global/<name> 或 @<绝对路径>/<name>），
    // projectRoot 缺失时跳过提交（防御非法 @/name）。
    const serverKey = toolDisableServerKey(server, state);
    if (serverKey === undefined) {
      input.checked = !input.checked;
      console.warn("[dsh-mcp-manager] projectRoot 缺失，跳过 tool-disable（非法 @/name 防御）");
      return;
    }
    void api<unknown>(state.API.toolDisable, {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        server: serverKey,
        tool,
        disabled: input.checked,
      }),
    })
      .then(() => actions.refresh())
      .catch((error: unknown) => {
        input.checked = !input.checked;
        console.warn("[dsh-mcp-manager] tool-disable failed:", error);
      });
  });
  label.appendChild(input);
  label.appendChild(document.createTextNode(tool));
  return label;
}

/** 折叠式工具清单（方案 2b）：summary 显示「工具（N）」，展开后 checkbox 列表。
 * openTools：C8 折叠态恢复集合（渲染前由 renderFloatPanel 收集，按 server 名）。 */
function renderFloatTools(
  server: McpServerListEntry,
  state: McpState,
  actions: UiActions,
  openTools: Set<string>,
): HTMLElement {
  const tools = Array.isArray(server.tools) ? server.tools : [];
  const disabledSet = new Set(Array.isArray(server.disabledTools) ? server.disabledTools : []);
  const details = el("details", { class: "dm-float-tools", dataset: { dmServer: server.name } });
  if (openTools.has(server.name)) details.open = true;
  details.appendChild(el("summary", { text: t("toolsCount", { n: tools.length }) }));
  const list = el("div", { class: "dm-float-tool-list" });
  for (const tool of tools) {
    list.appendChild(toolCheckbox(server, tool, disabledSet.has(tool), state, actions));
  }
  details.appendChild(list);
  return details;
}

/** 操作主次：按 status 判定（可连接 → primary），不依赖文案字面量。 */
function floatActionClass(server: McpServerListEntry): string {
  if (server.status === "failed" || server.status === "stopped")
    return "dm-float-action dm-primary";
  return "dm-float-action";
}

/**
 * 一行上的动作描述：按钮外观 + 打到哪个口 + 请求形状 + 失败告警的稳定标识。
 * tag 是 console 文案用的动作名（与 i18n 文案解耦：翻界面不改日志）。
 */
interface RowAction {
  className: string;
  label: string;
  url: string;
  method: "POST" | "PATCH";
  tag: string;
  /** 只有 PATCH 动作带载荷（连接/断开是纯 POST，历史形状如此）。 */
  body?: string;
}

/** 主操作（每行恰好一个）：connected → 断开；disabled → 启用；其余 → 连接。 */
export function primaryRowAction(
  server: McpServerListEntry,
  state: McpState,
  cwdQuery: string,
): RowAction {
  const query = `name=${encodeURIComponent(server.name)}&scope=${server.scope}${cwdQuery}`;
  const className = floatActionClass(server);
  if (server.status === "connected") {
    return {
      className,
      label: t("disconnect"),
      url: `${state.API.disconnect}?${query}`,
      method: "POST",
      tag: "disconnect",
    };
  }
  if (server.status === "disabled") {
    return {
      className,
      label: t("enable"),
      url: `${state.API.servers}?${query}`,
      method: "PATCH",
      tag: "enable",
      body: JSON.stringify({ enabled: true }),
    };
  }
  return {
    className,
    label: t("connect"),
    url: `${state.API.connect}?${query}`,
    method: "POST",
    tag: "connect",
  };
}

/** 禁用动作（仅非 disabled 行有）：URL 不带 cwd（历史形状如此，勿补）。 */
export function disableRowAction(server: McpServerListEntry, state: McpState): RowAction {
  return {
    className: "dm-float-action",
    label: t("disable"),
    url: `${state.API.servers}?name=${encodeURIComponent(server.name)}&scope=${server.scope}`,
    method: "PATCH",
    tag: "disable",
    body: JSON.stringify({ enabled: false }),
  };
}

/** 请求 init：带载荷的 PATCH 补 content-type；纯 POST 不带头（历史形状）。 */
export function rowRequestInit(action: RowAction): {
  method: string;
  headers?: Record<string, string>;
  body?: string;
} {
  if (action.body === undefined) return { method: action.method };
  return {
    method: action.method,
    headers: { "content-type": "application/json" },
    body: action.body,
  };
}

/** 动作按钮：点一下打口 → 成功后整面板刷新；失败只 warn（面板下次刷新自然回正）。 */
function rowActionButton(action: RowAction, actions: UiActions): HTMLElement {
  const button = el("button", { class: action.className });
  button.textContent = action.label;
  button.addEventListener("click", () => {
    void api<unknown>(action.url, rowRequestInit(action))
      .then(() => actions.refresh())
      .catch((error: unknown) => console.warn(`[dsh-mcp-manager] ${action.tag} failed:`, error));
  });
  return button;
}

/** 浮窗面板里的一行服务器。 */
function renderFloatRow(
  server: McpServerListEntry,
  state: McpState,
  actions: UiActions,
  opts: { tools: boolean; openTools?: Set<string>; stagger?: number } = { tools: true },
): HTMLElement {
  const failed = server.status === "failed" || server.status === "reconnecting";
  const row = el("div", {
    class: `dm-float-row${failed ? " dm-float-row--fail" : ""}${opts.stagger !== undefined ? " dm-stagger" : ""}`,
  });
  if (opts.stagger !== undefined) {
    row.style.animationDelay = `${Math.min(opts.stagger, 5) * 30}ms`;
  }
  row.appendChild(el("span", { class: "dm-dot", style: `background:${statusDot(server.status)}` }));
  row.appendChild(el("span", { class: "dm-float-name", text: server.name, title: server.name }));
  const tools = Array.isArray(server.tools) ? server.tools.length : 0;
  row.appendChild(
    el("span", {
      class: "dm-float-meta",
      text: pangu(t("serverMeta", { status: tStatus(server.status), tools })),
    }),
  );
  const actionsEl = el("div", { class: "dm-float-actions" });
  actionsEl.appendChild(
    rowActionButton(primaryRowAction(server, state, cwdQueryOf(state)), actions),
  );
  if (server.status !== "disabled") {
    actionsEl.appendChild(rowActionButton(disableRowAction(server, state), actions));
  }
  row.appendChild(actionsEl);
  if (opts.tools)
    row.appendChild(renderFloatTools(server, state, actions, opts.openTools ?? new Set()));
  return row;
}

/** 浮窗健康摘要（一行：运行/连接/失败）。 */
function renderFloatHealth(state: McpState): HTMLElement {
  const connected = state.counts.connected ?? 0;
  const connecting = (state.counts.connecting ?? 0) + (state.counts.reconnecting ?? 0);
  const failed = state.counts.failed ?? 0;
  const stopped = state.counts.stopped ?? 0;
  const parts: Node[] = [];
  parts.push(
    el("span", { class: "dm-health-ok", text: pangu(t("healthRunning", { n: connected })) }),
  );
  if (connecting > 0)
    parts.push(document.createTextNode(pangu(t("healthConnecting", { n: connecting }))));
  if (stopped > 0) parts.push(document.createTextNode(pangu(t("healthStopped", { n: stopped }))));
  if (failed > 0)
    parts.push(
      el("span", { class: "dm-health-bad", text: pangu(t("healthFailed", { n: failed })) }),
    );
  const line = el("div", { class: "dm-float-health" });
  parts.forEach((part, index) => {
    if (index > 0) line.appendChild(document.createTextNode(" · "));
    line.appendChild(part);
  });
  return line;
}

/**
 * 按状态分桶（桶序 = STATUS_ORDER，固定六态先建空桶）。未知状态归 stopped 桶——
 * 六态是唯一合法取值域，落到兜底桶而不是丢弃该行。
 */
export function bucketServersByStatus(
  list: McpServerListEntry[],
): Map<string, McpServerListEntry[]> {
  const byStatus = new Map<string, McpServerListEntry[]>();
  for (const group of STATUS_ORDER) byStatus.set(group.key, []);
  for (const server of list) {
    const bucket = byStatus.get(server.status) ?? byStatus.get("stopped");
    if (bucket !== undefined) bucket.push(server);
  }
  return byStatus;
}

/** 行级 stagger 序号：动画关闭返回 undefined（该行不加 dm-stagger、不进序）。 */
export function nextStagger(staggerBase: { n: number }, animate: boolean): number | undefined {
  if (!animate) return undefined;
  const current = staggerBase.n;
  staggerBase.n += 1;
  return current;
}

/** 按 scope 过滤并按状态序渲染一组服务器。 */
function appendScopeGroup(
  panel: Element,
  scope: string,
  list: McpServerListEntry[],
  state: McpState,
  actions: UiActions,
  openTools: Set<string>,
  staggerBase: { n: number },
  animateRows: boolean,
  titleOverride?: string,
  alert?: boolean,
): void {
  if (list.length === 0) return;
  const section = el("section", { class: "dm-float-group" });
  section.appendChild(
    el("div", {
      class: `dm-float-group-title${alert === true ? " dm-float-group-title--alert" : ""}`,
      text: titleOverride ?? (scope === "project" ? t("groupProject") : t("groupGlobal")),
    }),
  );
  const byStatus = bucketServersByStatus(list);
  for (const group of STATUS_ORDER) {
    const bucket = byStatus.get(group.key) ?? [];
    if (bucket.length === 0) continue;
    const ordered = [...bucket].sort((a: McpServerListEntry, b: McpServerListEntry) =>
      a.name.localeCompare(b.name),
    );
    for (const server of ordered) {
      section.appendChild(
        renderFloatRow(server, state, actions, {
          tools: true,
          openTools,
          stagger: nextStagger(staggerBase, animateRows),
        }),
      );
    }
  }
  panel.appendChild(section);
}

/** 浮窗标题的项目名：项目根末段；无项目根回落「全局会话」。 */
export function floatProjectName(state: McpState): string {
  const root = state.projectRoot;
  if (typeof root !== "string" || root === "") return t("floatGlobalSession");
  return root.split(/[\\/]/).filter(Boolean).pop() ?? root;
}

/** 收起浮窗并打开主面板（空态 CTA 与标题「管理」同动作）。 */
function openMainPanel(state: McpState, actions: UiActions): void {
  toggleFloat(state, actions, false);
  actions.showPanel();
}

/** 浮窗空态：一台服务器都没有时的说明 + 引导按钮。 */
function renderFloatEmpty(state: McpState, actions: UiActions): HTMLElement {
  const empty = el("div", { class: "dm-status" });
  empty.appendChild(el("div", { text: t("floatEmptyTitle") }));
  empty.appendChild(
    el("button", {
      class: "dm-float-action dm-primary",
      text: t("floatEmptyCta"),
      style: "margin-top:12px",
      onclick: () => openMainPanel(state, actions),
    }),
  );
  return empty;
}

/** 需要置顶提醒的服务器（失败 + 重连中）。 */
export function needsAttention(server: McpServerListEntry): boolean {
  return server.status === "failed" || server.status === "reconnecting";
}

/** 渲染浮窗下拉面板（健康摘要 + 失败优先 + scope 分组）。 */
export function renderFloatPanel(state: McpState, actions: UiActions): void {
  if (state.floatPanel === undefined) return;
  // C8：折叠态在重渲染前收集（details 重建会丢 open 属性）。
  const openTools = new Set<string>();
  for (const d of state.floatPanel.querySelectorAll<HTMLDetailsElement>("details.dm-float-tools")) {
    if (d.open && d.dataset.dmServer !== undefined) openTools.add(d.dataset.dmServer);
  }
  state.floatPanel.textContent = "";
  const head = el("div", { class: "dm-float-head" });
  const headText = el("div", { class: "dm-float-head-text" });
  headText.appendChild(el("div", { class: "dm-float-title", text: floatProjectName(state) }));
  headText.appendChild(renderFloatHealth(state));
  head.appendChild(headText);
  head.appendChild(
    el("button", { text: t("floatManage"), onclick: () => openMainPanel(state, actions) }),
  );
  state.floatPanel.appendChild(head);

  if (state.servers.length === 0) {
    state.floatPanel.appendChild(renderFloatEmpty(state, actions));
    if (state.floatOpen) placePanel(state);
    return;
  }

  const animateRows = state.floatPanel.dataset.dmStagger === "1";
  const staggerBase = { n: 0 };
  const attention = state.servers.filter(needsAttention);
  const rest = state.servers.filter((server: McpServerListEntry) => !needsAttention(server));
  appendScopeGroup(
    state.floatPanel,
    "attention",
    attention,
    state,
    actions,
    openTools,
    staggerBase,
    animateRows,
    t("groupAttention", { n: attention.length }),
    true,
  );
  for (const scope of ["project", "global"]) {
    appendScopeGroup(
      state.floatPanel,
      scope,
      rest.filter((server: McpServerListEntry) => server.scope === scope),
      state,
      actions,
      openTools,
      staggerBase,
      animateRows,
    );
  }
  delete state.floatPanel.dataset.dmStagger;
  if (state.floatOpen) placePanel(state);
}

/** 切换浮窗展开/收起（Apple Fluid：锚点→对角 scale；先渲染后定位）。 */
export function toggleFloat(state: McpState, actions: UiActions, force?: boolean): void {
  if (state.floatPanel === undefined) return;
  const next = force !== undefined ? force : !state.floatOpen;
  state.floatOpen = next;
  const panel = state.floatPanel;
  const pill = state.floatPill;
  if (next) {
    // F1：先渲染再定位。dataset 标记仅本次展开播行 stagger。
    panel.dataset.dmStagger = "1";
    panel.hidden = false;
    panel.classList.remove("dm-float-panel--closing", "dm-float-panel--open");
    renderFloatPanel(state, actions);
    placePanel(state);
    const armOpen = () => {
      if (!state.floatOpen) return;
      replayAnim(panel);
      panel.classList.add("dm-float-panel--open");
      pill?.classList.add("dm-float--open");
    };
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(armOpen);
    else armOpen();
    panel.focus({ preventScroll: true });
    return;
  }
  pill?.classList.remove("dm-float--open");
  panel.classList.remove("dm-float-panel--open");
  const finish = () => {
    if (state.floatOpen) return;
    panel.classList.remove("dm-float-panel--closing");
    panel.hidden = true;
  };
  if (typeof requestAnimationFrame === "function") {
    replayAnim(panel);
    panel.classList.add("dm-float-panel--closing");
    window.setTimeout(finish, 300);
  } else {
    finish();
  }
}

/** 水平锚点判定：left-* 贴左缘，其余贴右缘（胶囊与面板共用同一口径）。 */
export function anchorsLeft(position: string | undefined): boolean {
  return position === "top-left" || position === "bottom-left";
}

/** Fluid 展开原点：锚点所在的那个角（胶囊贴边角 → 面板向对角展开）。 */
export function transformOriginFor(isLeft: boolean, anchorBottom: boolean): string {
  if (anchorBottom) return isLeft ? "bottom left" : "bottom right";
  return isLeft ? "top left" : "top right";
}

/** 下拉面板定位（fixed 跟随胶囊，避免被滚动容器裁剪；四角感知 + 视口终 clamp）。 */
export function placePanel(state: McpState): void {
  if (state.floatPill === undefined || state.floatPanel === undefined) return;
  const pillRect = state.floatPill.getBoundingClientRect();
  if (pillRect.width === 0 && pillRect.height === 0) return;
  const panel = state.floatPanel;
  const position = state.mcpUiConfig?.position;
  const anchorBottom = panelAnchorForPosition(position) === "bottom";
  const isLeft = anchorsLeft(position);
  const gap = 6;
  // 垂直：底部锚点向上弹出（clamp 到视口上缘）/ 顶部锚点向下弹出（历史行为）。
  const rawTop = anchorBottom
    ? Math.max(6, pillRect.top - panel.offsetHeight - gap)
    : Math.max(6, pillRect.bottom + gap);
  // 水平：left 锚点面板左缘贴胶囊左缘；right 锚点面板右缘贴胶囊右缘
  // （等价换算为 left 后统一处理，保持与旧 right 定位相同的视觉结果）。
  const rawLeft = isLeft
    ? Math.max(10, Math.round(pillRect.left))
    : Math.max(10, Math.round(pillRect.right - panel.offsetWidth));
  // 终坐标视口 clamp（safe-area 语义：宿主无 viewport-fit=cover → inset 恒 0，
  // 自然退化为普通 clamp，桌面行为不回归）。
  const point = clampPointToViewport(
    rawLeft,
    rawTop,
    panel.offsetWidth,
    panel.offsetHeight,
    window.innerWidth,
    window.innerHeight,
  );
  panel.style.left = `${Math.round(point.x)}px`;
  panel.style.top = `${Math.round(point.y)}px`;
  panel.style.right = "auto";
  panel.style.transformOrigin = transformOriginFor(isLeft, anchorBottom);
}

/** 会话滚动容器：聊天消息实际滚动的区域（shell 的 data-conversation-scroll）。 */
export function conversationHost(): Element {
  return (
    document.querySelector("[data-conversation-scroll]") ??
    document.querySelector('[data-pane="conversation"]') ??
    document.querySelector(".pI_x6G_centerCol") ??
    document.body
  );
}

/** 全局 overlay 层：下拉面板挂这里（fixed 定位，避免被滚动容器裁剪）。 */
export function panelHost(): Element {
  return document.querySelector("[data-shell-overlay]") ?? document.body;
}

/**
 * 当前会话是否空白会话（空白会话用另一档垂直偏移）。取不到会话面一律判非空白。
 *
 * #1028：与 core/session.ts 共用 core/current-session.ts 单一接缝，判定改用官方口径
 * `retainedBy.mainView`；`blank` 直读官方 `SessionSummary.blank`，不从 cwd 空串推。
 */
export function isBlankSession(ctx: McpClientContext): boolean {
  const read = readCurrentSession(ctx?.sessions?.list);
  return read.kind === "session" && read.blank;
}

/** 从 settings.yaml 读取的配置决定新/老会话垂直偏移。 */
export function floatTopOffset(ctx: McpClientContext, state: McpState): number {
  const cfg = state.mcpUiConfig || {};
  const y = typeof cfg.offsetY === "number" ? cfg.offsetY : 8;
  const blankY = typeof cfg.blankY === "number" ? cfg.blankY : y;
  return isBlankSession(ctx) ? blankY : y;
}

/** 胶囊位置配置白名单：只认四个锚点，其余（含缺省）回落 top-right（历史行为）。 */
export function floatPositionOf(cfg: ClientUiConfig): ClientUiConfig["position"] {
  const position = cfg.position;
  if (position === "top-left" || position === "bottom-right" || position === "bottom-left")
    return position;
  return "top-right";
}

/** 胶囊定位入参（锚点 + 偏移）：位置白名单归一、水平偏移缺省 8、垂直偏移按会话形态。 */
export function pillAnchors(
  cfg: ClientUiConfig,
  ctx: McpClientContext,
  state: McpState,
): { isLeft: boolean; isBottom: boolean; offsetX: number; offsetY: number } {
  const position = floatPositionOf(cfg);
  return {
    isLeft: anchorsLeft(position),
    isBottom: panelAnchorForPosition(position) === "bottom",
    offsetX: typeof cfg.offsetX === "number" ? cfg.offsetX : 8,
    offsetY: floatTopOffset(ctx, state),
  };
}

/** 底部锚点是否改用 composer seat 上缘当下边界（#128：仅非 wide 断点）。 */
export function usesComposerSeat(isBottom: boolean, bp: FloatBreakpoint): boolean {
  return isBottom && bp !== "wide";
}

/** 底部锚点的容器下边界：composer seat 贴底时改用 seat 上缘（胶囊上移到输入区上方）。 */
export function dockedBottomEdge(containerRect: { top: number; bottom: number }): number {
  const seat = document.querySelector<HTMLElement>("[data-composer-seat]");
  const seatRect = seat !== null ? seat.getBoundingClientRect() : null;
  return bottomAnchorEdge(
    containerRect.bottom,
    seatRect?.top ?? null,
    composerDockedAtBottom(seatRect, containerRect),
  );
}

/** 胶囊定位纯计算的入参（DOM 读口在调用面，坐标算式在这里，可直测）。 */
interface PillPlacementInput {
  rect: { top: number; bottom: number; left: number; right: number };
  width: number;
  height: number;
  isLeft: boolean;
  isBottom: boolean;
  offsetX: number;
  offsetY: number;
  /** 底部锚点下边界（已含 composer seat 改写，见 dockedBottomEdge）。 */
  bottomEdge: number;
  viewportW: number;
  viewportH: number;
}

/**
 * 胶囊终坐标（纯计算）：水平按锚点贴容器左右缘、垂直按锚点（bottom 从下边界上推、
 * clamp 到视口上缘；top 从容器顶下移），最后统一走视口 clamp。
 */
export function pillPlacement(input: PillPlacementInput): ViewportPoint {
  const rawLeft = input.isLeft
    ? input.rect.left + input.offsetX
    : input.rect.right - input.width - input.offsetX;
  const rawTop = input.isBottom
    ? Math.max(6, input.bottomEdge - input.height - input.offsetY)
    : input.rect.top + input.offsetY;
  return clampPointToViewport(
    rawLeft,
    rawTop,
    input.width,
    input.height,
    input.viewportW,
    input.viewportH,
  );
}

/**
 * 挂载浮窗：胶囊继续挂在会话滚动容器（scrollBody）内并钉住右上角，下拉面板
 * fixed 跟随。返回 disposer 函数。
 */
export function mountFloat(ctx: McpClientContext, state: McpState, actions: UiActions): () => void {
  const pill = el("button", {
    type: "button",
    class: "dm-float",
    "aria-label": t("floatAriaLabel"),
    title: t("floatTitle"),
  });
  pill.dataset.dshMcpFloat = "";
  pill.addEventListener("click", () => toggleFloat(state, actions));
  const panel = el("div", { class: "dm-float-panel", role: "dialog" });
  panel.hidden = true;
  panel.tabIndex = -1;
  state.floatPill = pill;
  state.floatPanel = panel;
  // 胶囊挂会话滚动容器，下拉面板挂 shell.overlay（fixed 定位，仍与通知同一层）。
  const panelRoot = panelHost();
  if (panel.parentElement !== panelRoot) panelRoot.appendChild(panel);

  // 失去焦点后自动关闭：焦点离开胶囊/面板时收起下拉框。
  const onFocusOut = (event: FocusEvent) => {
    if (!state.floatOpen) return;
    const next = event.relatedTarget as Node | null;
    if (next !== null && (state.floatPanel?.contains(next) || state.floatPill?.contains(next)))
      return;
    toggleFloat(state, actions, false);
  };
  document.addEventListener("focusout", onFocusOut);
  // Esc 关闭下拉面板（与模态 panel.ts C4 同语义；具名函数配对清理防泄漏）。
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.defaultPrevented) return;
    if (event.key === "Escape" && state.floatOpen) toggleFloat(state, actions, false);
  };
  document.addEventListener("keydown", onKeyDown);

  let host: Element | null | undefined;

  /**
   * 按 settings.yaml 配置把胶囊定位到对话容器四角之一（双轴：left/right × top/bottom）。
   * 同时：按会话容器宽度判定断点档位写 data 属性（CSS 按档位切换触控/布局样式）、
   * 应用层级基准（胶囊与主面板同取配置值）、终坐标视口 clamp。
   */
  const updateFloat = () => {
    const best = conversationHost();
    if (best === null || best === undefined) return;
    const rect = best.getBoundingClientRect();
    const cfg = state.mcpUiConfig || {};
    // 断点判定基准 = conversationHost rect 宽度（JS 判定，非纯 @media——
    // 防桌面窄窗 / iPad Slide Over 误触发）；data 属性驱动 CSS 档位样式。
    const bp = breakpointForWidth(rect.width);
    if (pill.dataset.dmBp !== bp) pill.dataset.dmBp = bp;
    if (panel.dataset.dmBp !== bp) panel.dataset.dmBp = bp;
    // 层级：胶囊与点击后弹出的主面板 computed z-index 一律取配置基准（clamp 1-9000），
    // 不再派生 +30（维护者 2026-08-28 要求 #128，B2）；面板内子浮层可派生见 panelZIndexFor。
    const zBase = clampZIndexBase(cfg.zIndexBase, DEFAULT_Z_INDEX_BASE);
    pill.style.zIndex = String(zBase);
    panel.style.zIndex = String(zBase);
    const anchors = pillAnchors(cfg, ctx, state);
    pill.style.position = "fixed";
    // 垂直：bottom 锚点 → 下边界 - 高 - y（clamp 到视口上缘防溢出）；top 锚点 → 容器顶 + y。
    // #128 重开回归修复：bottom-* 在断点非 wide 且 composer seat 贴底时，下边界换成
    // seat.top（胶囊上移到输入区上方，避免遮挡输入卡片/底部状态条）；否则维持
    // container.bottom（桌面零回归）。水平：left 锚点 → 容器左缘 + offsetX；
    // right 锚点 → 容器右缘 - 宽 - offsetX。两者算式都在 pillPlacement 里。
    const bottomEdge = usesComposerSeat(anchors.isBottom, bp)
      ? dockedBottomEdge(rect)
      : rect.bottom;
    const point = pillPlacement({
      rect,
      width: pill.offsetWidth,
      height: pill.offsetHeight,
      ...anchors,
      bottomEdge,
      viewportW: window.innerWidth,
      viewportH: window.innerHeight,
    });
    pill.style.left = `${Math.round(point.x)}px`;
    pill.style.top = `${Math.round(point.y)}px`;
    pill.style.right = "auto";
    if (state.floatOpen) placePanel(state);
  };
  state.updateFloatState = updateFloat;

  const listeners: (() => void)[] = [];

  /** rAF 合并调度：同帧多次 scroll/resize/vv-resize 只重算一次（#128 第 7 条）。 */
  let rafId = 0;
  const scheduleUpdate = () => {
    if (rafId !== 0) return;
    rafId = requestAnimationFrame(() => {
      rafId = 0;
      updateFloat();
    });
  };

  /** orientationchange 后延迟一帧重算：横竖屏切换瞬间 rect 尚未更新（规格第 2 条）。 */
  const onOrientationChange = () => {
    scheduleUpdate();
  };

  /** 软键盘弹出/收起：visualViewport resize 监听（iOS 13+ 全支持），fixed 元素跟随视口。 */
  const onVisualViewportResize = () => {
    scheduleUpdate();
  };

  const attachListeners = (target: Element) => {
    for (const detach of listeners.splice(0)) detach();
    target.addEventListener("scroll", scheduleUpdate, { passive: true });
    window.addEventListener("resize", scheduleUpdate);
    window.addEventListener("orientationchange", onOrientationChange);
    window.visualViewport?.addEventListener("resize", onVisualViewportResize);
    listeners.push(() => {
      target.removeEventListener("scroll", scheduleUpdate);
      window.removeEventListener("resize", scheduleUpdate);
      window.removeEventListener("orientationchange", onOrientationChange);
      window.visualViewport?.removeEventListener("resize", onVisualViewportResize);
    });
    updateFloat();
  };

  /**
   * 放置/迁移：每次调用都重新求最佳宿主（scrollBody 优先），胶囊跟着它走——
   * 即使初始化时 scrollBody 尚未渲染（退回 body），一旦出现就迁移。
   */
  const place = () => {
    const best = conversationHost();
    if (best === null || best === undefined) return false;
    if (host !== best || pill.parentElement !== best) {
      host = best;
      if (pill.parentElement !== null) pill.remove();
      best.appendChild(pill);
      attachListeners(best);
    }
    return true;
  };
  // MutationObserver 去抖：宿主 DOM 批量变更（会话切换渲染多帧）合并到一帧处理，
  // 避免高频 childList 变更下 place()/updateFloat() 空转（#128 第 7 条）。
  let observerRafId = 0;
  const schedulePlace = () => {
    if (observerRafId !== 0) return;
    observerRafId = requestAnimationFrame(() => {
      observerRafId = 0;
      place();
    });
  };
  const observer = new MutationObserver(schedulePlace);
  if (place()) {
    observer.observe(document.body, { childList: true, subtree: true });
  } else {
    const wait = new MutationObserver(() => {
      if (place()) {
        wait.disconnect();
        observer.observe(document.body, { childList: true, subtree: true });
      }
    });
    wait.observe(document.body, { childList: true, subtree: true });
  }
  renderPill(state);
  return () => {
    state.updateFloatState = undefined;
    document.removeEventListener("focusout", onFocusOut);
    document.removeEventListener("keydown", onKeyDown);
    observer.disconnect();
    for (const detach of listeners.splice(0)) detach();
    if (rafId !== 0) {
      cancelAnimationFrame(rafId);
      rafId = 0;
    }
    if (observerRafId !== 0) {
      cancelAnimationFrame(observerRafId);
      observerRafId = 0;
    }
    pill.remove();
    panel.remove();
    state.floatPill = undefined;
    state.floatPanel = undefined;
    state.floatOpen = false;
  };
}

/**
 * dsh-mcp-manager — 客户端模态面板生命周期。
 *
 * 面板的打开/关闭/tab 切换/数据刷新。
 * 跨模块渲染（renderServers / buildQuickAdd / renderPill / renderFloatPanel）
 * 直接 import 用到的模块——本模块是 feature 模块的汇聚点，构成单向依赖图：
 * panel → servers / quick-add / float。
 */

import { el } from "../core/dom.ts";
import { api } from "../core/api.ts";
import { t } from "../../../../../shared/client/i18n.js";
import type { McpCounts, McpServerListEntry, McpState, UiActions } from "../core/state.ts";
import { renderServers } from "./servers.ts";
import { buildQuickAdd } from "./quick-add.ts";
import { renderPill, renderFloatPanel } from "./float.ts";

/** 模块级单飞去重句柄（invalidate 单飞：同一时刻只有一个 in-flight 拉取）。 */
let inflight: Promise<boolean> | undefined;

/** C4：Escape keydown 清理回调登记（WeakMap 避免污染 McpState 接口）。 */
const keydownCleanups = new WeakMap<McpState, () => void>();

/**
 * 刷新服务器列表与浮窗摘要（单飞：in-flight 复用；#111 变更点驱动）。
 * 返回 true=成功；false=失败（调用方按退避重试）。
 */
export function refresh(state: McpState, actions: UiActions): Promise<boolean> {
  if (inflight !== undefined) return inflight;
  inflight = doRefresh(state, actions).finally(() => {
    inflight = undefined;
  });
  return inflight;
}

/** 健康摘要文案：按 counts 逐档拼段，无段时退到「共 N 台」。缺档位按 0 读（服务端省略未发生的档）。 */
function countsSummaryText(state: McpState): string {
  const parts: string[] = [];
  const { connected = 0, connecting = 0, reconnecting = 0, failed = 0 } = state.counts;
  if (connected > 0) parts.push(t("countsConnected", { n: connected }));
  if (connecting > 0 || reconnecting > 0)
    parts.push(t("countsConnecting", { n: connecting + reconnecting }));
  if (failed > 0) parts.push(t("countsFailed", { n: failed }));
  return parts.length > 0
    ? t("countsSummary", { n: state.servers.length, parts: parts.join(" · ") })
    : t("countsSummaryOnly", { n: state.servers.length });
}

/** 健康摘要徽标（面板头 .dm-counts）：文案由 countsSummaryText 给；失败计数在文案里就地
 *  标红（与浮窗同语义）。徽标缺席（面板头未建）时静默跳过。 */
function renderCountsBadge(state: McpState): void {
  const countsEl = document.querySelector(".dm-counts");
  if (countsEl === null) return;
  const summary = countsSummaryText(state);
  const failed = state.counts.failed ?? 0;
  if (failed > 0 && typeof summary === "string") {
    const failedText = t("countsFailed", { n: failed });
    countsEl.textContent = "";
    summary.split(failedText).forEach((chunk, index) => {
      if (index > 0) {
        countsEl.appendChild(el("span", { class: "dm-health-bad", text: failedText }));
      }
      if (chunk !== "") countsEl.appendChild(document.createTextNode(chunk));
    });
    return;
  }
  countsEl.textContent = summary;
}

/** 实际拉取（单飞内部）。 */
async function doRefresh(state: McpState, actions: UiActions): Promise<boolean> {
  try {
    // #324：GET /servers 不再带 cwd——服务端已忽略该参数（纯读快照，零副作用），
    // 会话切换只走 POST /api/dsh-mcp/session（bindSession cwd 变化时触发）。
    // 带 cwd 曾触发服务端 setSession → 广播 → 客户端再刷新的自激循环。
    const payload = await api<{
      servers?: McpServerListEntry[];
      counts?: McpCounts;
      projectRoot?: string;
    }>(state.API.servers);
    state.servers = payload.servers ?? [];
    state.counts = payload.counts ?? {};
    state.projectRoot = payload.projectRoot;
    renderPill(state);
    if (state.floatOpen) renderFloatPanel(state, actions);
    renderCountsBadge(state);
    if (state.bodyEl !== undefined && state.activeTab === "servers") renderServers(state, actions);
    return true;
  } catch (error) {
    if (state.bodyEl !== undefined && state.activeTab === "servers") {
      state.bodyEl.textContent = "";
      state.bodyEl.appendChild(
        el("div", {
          class: "dm-status",
          text: t("loadFail", { msg: error instanceof Error ? error.message : String(error) }),
        }),
      );
    }
    return false;
  }
}

/** 切换面板 tab（servers / quick）。 */
export function switchTab(state: McpState, actions: UiActions, tab: string): void {
  state.activeTab = tab;
  for (const tabEl of document.querySelectorAll<HTMLElement>(".dm-tab")) {
    tabEl.dataset.active = tabEl.dataset.tab === tab ? "true" : "";
  }
  if (state.bodyEl === undefined) return;
  state.bodyEl.textContent = "";
  if (tab === "servers") {
    if (state.servers.length === 0) void refresh(state, actions);
    else renderServers(state, actions);
  } else {
    const page = buildQuickAdd(state, actions);
    state.bodyEl.appendChild(page);
  }
}

/** 关闭模态面板（Fluid：卡片中心收束 + 遮罩淡出；完成后再 hidden）。
 *
 * R1 状态同翻：state.open=false 的同一同步块内摘除 aria-modal（不经 300ms
 * 动画回调——动画被打断/定时器漂移时标记与状态永久错位，见 #947）。
 * R2 常驻壳无标记：hidden 元素仍被 querySelector 命中，故必须摘属性而非
 * 置 "false"（裸 [aria-modal] 存在检查仍命中 "false"，且关闭态留 "false"
 * 语义错误）。R6 关还焦：同步把焦点还给打开者（便宜且安全）。
 */
export function close(state: McpState): void {
  if (state.overlay === undefined) return;
  state.open = false;
  // 与 state.open 同步翻转：card 缺失属创建/销毁不对称，显式分支不断言静默。
  if (state.card !== undefined) state.card.removeAttribute("aria-modal");
  // R6 还焦：opener 仍在文档内才恢复（已卸载/非元素则跳过，不抛）。
  const opener = state.panelOpener;
  state.panelOpener = undefined;
  if (opener !== undefined && opener !== null && typeof opener.focus === "function") {
    try {
      if (typeof opener.isConnected !== "boolean" || opener.isConnected) {
        opener.focus({ preventScroll: true });
      }
    } catch {
      // 焦点恢复失败不影响关闭语义，只 warn 不抛（绝不让 GUI 挂掉）。
      console.warn("[dsh-mcp-manager] panel opener focus restore skipped");
    }
  }
  const overlay = state.overlay;
  overlay.classList.remove("dm-overlay--open");
  const finish = () => {
    if (state.open) return;
    overlay.classList.remove("dm-overlay--closing");
    overlay.hidden = true;
  };
  if (typeof requestAnimationFrame === "function") {
    overlay.style.animation = "none";
    void overlay.offsetWidth;
    overlay.style.animation = "";
    overlay.classList.add("dm-overlay--closing");
    // 与 CSS .dm-overlay--closing .dm-card 的 300ms 对齐
    window.setTimeout(finish, 300);
  } else {
    finish();
  }
}

/** 打开模态面板（首次调用时创建 DOM 结构；Fluid：中心 scale 0.78→1）。 */
export function showPanel(state: McpState, actions: UiActions): void {
  if (state.overlay === undefined) {
    state.overlay = el("div", { class: "dm-overlay", hidden: true });
    state.overlay!.addEventListener("click", (event: MouseEvent) => {
      if (event.target === state.overlay) close(state);
    });
    state.card = el("div", { class: "dm-card" });

    const head = el("div", { class: "dm-head" });
    head.appendChild(el("h2", { text: t("panelTitle") }));
    head.appendChild(el("span", { class: "dm-counts", text: "" }));
    head.appendChild(
      el("button", { text: t("refresh"), onclick: () => void refresh(state, actions) }),
    );
    // C10：首次构建面板头后立刻拉一次（与打开路径 refresh 同源，单飞去重）。
    void refresh(state, actions);
    head.appendChild(el("button", { text: t("close"), onclick: () => close(state) }));
    state.card!.appendChild(head);
    // role 保留（静态语义；hidden 子树 AT-irrelevant）。aria-modal 不在此写：
    // 单点写入见本函数公共路径（state.open=true 后无条件 set），与 close() 的
    // 同步 removeAttribute 配对（R1），两处写同一值会漂移。
    state.card!.setAttribute("role", "dialog");
    state.card!.setAttribute("aria-label", t("panelTitle"));

    const tabs = el("div", { class: "dm-tabs" });
    tabs.appendChild(
      el("button", {
        class: "dm-tab",
        dataset: { tab: "servers" },
        text: t("tabServers"),
        onclick: () => switchTab(state, actions, "servers"),
      }),
    );
    tabs.appendChild(
      el("button", {
        class: "dm-tab",
        dataset: { tab: "quick" },
        text: t("tabQuickAdd"),
        onclick: () => switchTab(state, actions, "quick"),
      }),
    );
    state.card!.appendChild(tabs);

    state.bodyEl = el("div", { class: "dm-body" });
    state.card!.appendChild(state.bodyEl!);
    state.overlay!.appendChild(state.card!);
    document.body.appendChild(state.overlay!);

    // C4 keydown 泄漏修复：Escape 监听改具名函数并经 WeakMap 登记清理
    // 回调（disposePanel 配对 removeEventListener）——匿名监听器在 HMR/重复
    // apply 下无移除路径，会随每次 apply 累积。
    const onKeyDown = (event: KeyboardEvent) => {
      // R4 共享键让位：他人已 preventDefault 即不再关（多弹窗可组合）。
      if (event.defaultPrevented) return;
      if (event.key === "Escape" && state.open) close(state);
    };
    document.addEventListener("keydown", onKeyDown);
    keydownCleanups.set(state, () => document.removeEventListener("keydown", onKeyDown));
  }
  // R6 记录 opener（当前聚焦元素；body/非元素由 close() 侧守卫过滤）。
  // 进焦不做（R6：聚关闭按钮以外的文本控件会唤起移动端键盘+布局跳动）。
  // 已 open 时重入不覆写：焦点已在面板内，重记会把还焦落到 hidden 子树节点。
  if (!state.open) {
    state.panelOpener =
      typeof document !== "undefined" && document.activeElement instanceof HTMLElement
        ? document.activeElement
        : undefined;
  }
  state.open = true;
  // R1 单点写入：重开路径（含 close→300ms 内重开竞态）一律恢复 true，与
  // close() 的同步摘除配对，幂等。
  if (state.card !== undefined) state.card.setAttribute("aria-modal", "true");
  state.overlay!.hidden = false;
  state.overlay!.classList.remove("dm-overlay--closing");
  const armOpen = () => {
    if (!state.open || state.overlay === undefined) return;
    state.overlay.style.animation = "none";
    void state.overlay.offsetWidth;
    state.overlay.style.animation = "";
    state.overlay.classList.add("dm-overlay--open");
  };
  if (typeof requestAnimationFrame === "function") requestAnimationFrame(armOpen);
  else armOpen();
  // C10：面板打开主动刷新（refresh 单飞去重，与 switchTab 的空列表刷新重叠无害）——
  // 面板可能停在关闭期间的旧快照上；打开即拉最新数据消除该窗口。
  void refresh(state, actions);
  switchTab(state, actions, "servers");
}

/** C4：卸载配对清理（index.ts effect disposer 调用）——移除 Escape keydown 监听。 */
export function disposePanel(state: McpState): void {
  const cleanup = keydownCleanups.get(state);
  if (cleanup !== undefined) {
    cleanup();
    keydownCleanups.delete(state);
  }
}

/**
 * dsh-mcp-manager — 客户端「快速接入」页：表单与 mcpServers JSON 导入。
 *
 * 表单构建、读写、编辑、保存、重置；跨模块动作（refresh / switchTab）经
 * actions 注入，不直接引用 panel 模块，避免循环依赖。
 */

import { el } from "../core/dom.ts";
import { api } from "../core/api.ts";
import { t } from "../../../../../shared/client/i18n.js";
import type { McpState, UiActions } from "../core/state.ts";
import type { McpManagerServerInput, McpServerListEntry } from "../../shared/interface.ts";

/** 解析 "KEY: VALUE" / "KEY=VALUE" 多行文本为对象。 */
export function parseKV(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === "") continue;
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*[:=]\s*(.*)$/);
    if (match === null) continue;
    const value = match[2].trim();
    if (value !== "") out[match[1]] = value;
    else out[match[1]] = "";
  }
  return out;
}

/**
 * #770-A3 只读投影回写 guard：投影值永不进入写路径。
 * - env/headers 在投影中整体省略（无占位符），表单空白即省略、宿主沿用既有；
 * - url 投影含 B8 脱敏占位符 "[REDACTED]"（或其 URL 序列化形态）时视为未改动，
 *   保存时省略该字段（PATCH 沿用既有；迁移 POST 缺 url 则中止并提示重填）。
 */
export function isProjectionValue(value: unknown): boolean {
  return (
    typeof value === "string" && (value.includes("[REDACTED]") || value.includes("%5BREDACTED%5D"))
  );
}

/** 当前表单选择的归属（project/global）。 */
export function formScopeValue(state: McpState): string {
  if (
    state.formScope !== undefined &&
    (state.formScope.value === "project" || state.formScope.value === "global")
  ) {
    return state.formScope.value;
  }
  return state.projectRoot !== undefined && state.projectRoot !== "" ? "project" : "global";
}

/** 当前会话 cwd（POST body 携带，宿主据此切换项目级 MCP）。 */
export function currentCwdBody(state: McpState): Record<string, string> {
  return typeof state.currentCwd === "string" && state.currentCwd !== ""
    ? { cwd: state.currentCwd }
    : {};
}

/** transport 收窄谓词：只认 McpManagerServerInput 联合内的两个字面量。 */
export function isServerTransport(value: string): value is McpManagerServerInput["transport"] {
  return value === "stdio" || value === "streamable-http";
}

/** 表单 transport 取值：越界值（手改 DOM）判 stdio，收窄免断言。 */
export function formTransportValue(state: McpState): McpManagerServerInput["transport"] {
  const value = state.formTransport?.value ?? "stdio";
  return isServerTransport(value) ? value : "stdio";
}

/** stdio 表单字段：command 恒写入；args / env / cwd 为空不落键（缺省形态与历史一致）。 */
export function readStdioFormFields(
  state: McpState,
): Pick<McpManagerServerInput, "command" | "args" | "env" | "cwd"> {
  const fields: Pick<McpManagerServerInput, "command" | "args" | "env" | "cwd"> = {
    command: controlText(state.formCommand).trim(),
  };
  const args = controlText(state.formArgs)
    .split(",")
    .map((part: string) => part.trim())
    .filter(Boolean);
  if (args.length > 0) fields.args = args;
  const env = parseKV(controlText(state.formEnv));
  if (Object.keys(env).length > 0) fields.env = env;
  const cwd = controlText(state.formCwd).trim();
  if (cwd !== "") fields.cwd = cwd;
  return fields;
}

/** 表单控件的当前文本（未构建的控件回落空串；输入框与文本域同形）。 */
export function controlText(control: { value: string } | undefined): string {
  return control?.value ?? "";
}

/** streamable-http 表单字段：url 恒写入；headers 空表不落键。 */
export function readHttpFormFields(
  state: McpState,
): Pick<McpManagerServerInput, "url" | "headers"> {
  const fields: Pick<McpManagerServerInput, "url" | "headers"> = {
    url: controlText(state.formUrl).trim(),
  };
  const headers = parseKV(controlText(state.formHeaders));
  if (Object.keys(headers).length > 0) fields.headers = headers;
  return fields;
}

/** 表单数据 → 服务器配置对象（scope 由 formScope 决定）。 */
export function readForm(state: McpState): McpManagerServerInput {
  const server: McpManagerServerInput = {
    name: state.formName?.value.trim() ?? "",
    transport: formTransportValue(state),
    enabled: state.formEnabled?.checked ?? true,
  };
  // transport 是 McpManagerServerInput 的判别位：两侧字段各自成函数，母体只做分流。
  if (server.transport === "stdio") Object.assign(server, readStdioFormFields(state));
  else Object.assign(server, readHttpFormFields(state));
  return server;
}

/** 重置表单为默认值。 */
export function resetForm(state: McpState): void {
  state.editingName = undefined;
  state.editing = undefined;
  if (state.formName === undefined) return;
  state.formName.value = "";
  state.formScope!.value =
    state.projectRoot !== undefined && state.projectRoot !== "" ? "project" : "global";
  state.formTransport!.value = "stdio";
  state.formCommand!.value = "";
  state.formArgs!.value = "";
  state.formEnv!.value = "";
  state.formCwd!.value = "";
  state.formUrl!.value = "";
  state.formHeaders!.value = "";
  state.formEnabled!.checked = true;
  state.formTransport!.dispatchEvent(new Event("change"));
  const title = document.getElementById("dm-form-title");
  if (title !== null) title.textContent = t("addServer");
  const cancel = document.querySelector<HTMLButtonElement>("[data-dm-cancel]");
  if (cancel !== null) cancel.disabled = true;
}

/** KV 表单字段回填：缺键（投影省略）清零，防旧值被 readForm 原样读回落盘。 */
export function fillKvField(
  input: HTMLTextAreaElement | undefined,
  table: Record<string, string> | undefined,
  separator: "=" | ": ",
): void {
  if (input === undefined) return;
  input.value =
    table === undefined
      ? ""
      : Object.entries(table)
          .map(([key, value]) => `${key}${separator}${value}`)
          .join("\n");
}

/** 用服务器数据填充表单（编辑模式）。 */
export function fillForm(state: McpState, fill: McpServerListEntry): void {
  // C1 链路修复：不再调 resetForm()——resetForm 会清空 editingName，导致
  // beginEdit 设置的编辑态丢失、saveForm 恒走 POST → 宿主抛 already exists
  // （编辑保存整体坏死）。表单元素由 buildQuickAdd 按 state.editing 构建，
  // 此处仅覆盖字段值，编辑态（editingName）保持 beginEdit 设定。
  if (fill.name !== undefined) state.formName!.value = fill.name;
  state.formTransport!.value = fill.transport ?? "stdio";
  if (fill.command !== undefined) state.formCommand!.value = fill.command;
  if (Array.isArray(fill.args)) state.formArgs!.value = fill.args.join(", ");
  // #770-A3：投影省略 env/headers（缺键）时表单清零——残留旧值会被 readForm
  // 原样读回并 PATCH 落盘（占位符同理）；缺键在宿主即「沿用既有」。
  fillKvField(state.formEnv, fill.env, "=");
  if (fill.cwd !== undefined) state.formCwd!.value = fill.cwd;
  // url 投影为 B8 脱敏展示值（含占位符时仅展示用，保存时由 saveForm 省略，见上）。
  if (fill.url !== undefined) state.formUrl!.value = fill.url;
  fillKvField(state.formHeaders, fill.headers, ": ");
  // C1 enabled 回填：resetForm 强制 checked=true，编辑 enabled:false 的服务器
  // 必须回填，否则保存时被静默重新启用并自动连接（宿主 update 分支）。
  if (state.formEnabled !== undefined) state.formEnabled.checked = fill.enabled !== false;
  state.formTransport!.dispatchEvent(new Event("change"));
}

/** 迁移式保存判据：正在编辑，且（改名 或 改归属）。宿主 PATCH 按 (scope,name) 定位且
 * 强制沿用定位名，故这两类改动必须走 POST+DELETE（见 performSaveRequest）。 */
export function isMigratedEdit(
  state: McpState,
  server: McpManagerServerInput,
  payload: Record<string, unknown>,
): boolean {
  const editingName = state.editingName;
  if (editingName === undefined) return false;
  const serverName = typeof server.name === "string" ? server.name : "";
  if (editingName !== serverName) return true;
  const editScope = state.editing?.scope;
  return editScope !== undefined && editScope !== payload.scope;
}

/** 投影 URL 含占位符时是否必须中止保存：迁移 POST 与新建都无既有可沿用 → 中止提示重填。 */
export function urlPlaceholderBlocks(
  state: McpState,
  server: McpManagerServerInput,
  payload: Record<string, unknown>,
): boolean {
  return !isEditing(state) || isMigratedEdit(state, server, payload);
}

/** 写路径 env/headers 占位符清扫：整表清空即删键，否则逐键剔除（防手工粘贴/直调污染）。 */
function stripProjectionTables(payload: Record<string, unknown>): void {
  for (const key of PROJECTION_TABLES) {
    const table = payload[key];
    if (!isPlainRecord(table)) continue;
    const kept = Object.entries(table).filter(([, value]) => !isProjectionValue(value));
    if (kept.length === 0) delete payload[key];
    else payload[key] = Object.fromEntries(kept);
  }
}

/** 纯对象表判定（env/headers 表；null 与数组都不算表）。类型谓词，收窄后免断言。 */
export function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** 整表可能被投影省略的两张凭据表（清扫面）。 */
const PROJECTION_TABLES: readonly ("env" | "headers")[] = ["env", "headers"];

/** 是否处于编辑态（editingName 已设）。 */
export function isEditing(state: McpState): boolean {
  return state.editingName !== undefined;
}

/** 保存表单（新增或更新）。 */
export async function saveForm(state: McpState, actions: UiActions): Promise<void> {
  const server = readForm(state);
  try {
    const payload: Record<string, unknown> = {
      ...server,
      scope: formScopeValue(state),
      ...currentCwdBody(state),
    };
    // #770-A3：投影 URL（含占位符）永不进入写路径——PATCH 省略即沿用既有；
    // 迁移 POST 无既有可保，含占位符即中止并提示重填真值。
    const urlIsProjection = typeof payload.url === "string" && isProjectionValue(payload.url);
    if (urlIsProjection && urlPlaceholderBlocks(state, server, payload)) {
      window.alert(t("saveFail", { msg: "URL 含脱敏占位符，请重填真实 URL 后再保存" }));
      return;
    }
    if (urlIsProjection) delete payload.url;
    // env/headers 占位符同理（投影本不下发占位符，此处防手工粘贴/直调污染写路径）。
    stripProjectionTables(payload);
    if (!(await performSaveRequest(state, server, payload))) return;
    resetForm(state);
    await actions.refresh();
  } catch (error) {
    window.alert(t("saveFail", { msg: error instanceof Error ? error.message : String(error) }));
  }
}

/** JSON 写请求的公共 init（PATCH / POST 共用）。 */
export function jsonWriteInit(payload: Record<string, unknown>): {
  method: "POST" | "PATCH";
  headers: Record<string, string>;
  body: string;
} {
  return {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(payload),
  };
}

/**
 * 保存执行面（三种落点）与中止信号。
 * C11 迁移式保存：宿主 PATCH 按 (scope,name) 定位且强制沿用定位名——编辑改名/改归属
 * 会 404 not found 无引导。先 POST 新条目再 DELETE 旧条目，任何失败即抛（保留原条目，
 * 由 saveForm 的 catch alert），避免半迁移脏数据。
 * @returns false = 已中止（大声失败），调用方不得 resetForm / refresh。
 */
export async function performSaveRequest(
  state: McpState,
  server: McpManagerServerInput,
  payload: Record<string, unknown>,
): Promise<boolean> {
  if (isMigratedEdit(state, server, payload)) {
    // #770-L2：改名/改归属迁移丢 stdio 秘密——POST 新条目无既有可沿用，
    // 省略的 env/headers 即永久丢失。M7 大声失败：原条目有秘密时无条件中止
    // （表单即便已填值也不放行：payload 完整值放行本次不做，保持 fail-closed）。
    // 文案须指引手动路径（新建同名条目填真值后删旧条目），不得承诺“重填后保存”
    // ——无条件拦截下该后续路径不存在，旧文案误导。
    if (state.editing?.hasSecrets === true) {
      window.alert(
        t("saveFail", {
          msg: "改名/改归属迁移不会带入原有凭据，请新建同名条目并填写真实凭据，确认可用后再删除旧条目",
        }),
      );
      return false;
    }
    await api<unknown>(state.API.servers, jsonWriteInit(payload));
    await api<unknown>(
      `${state.API.servers}?name=${encodeURIComponent(state.editingName ?? "")}&scope=${state.editing?.scope}`,
      { method: "DELETE" },
    );
    return true;
  }
  if (isEditing(state)) {
    const query = `name=${encodeURIComponent(state.editingName ?? "")}&scope=${formScopeValue(state)}`;
    await api<unknown>(`${state.API.servers}?${query}`, {
      ...jsonWriteInit(payload),
      method: "PATCH",
    });
    return true;
  }
  await api<unknown>(state.API.servers, jsonWriteInit(payload));
  return true;
}

/** 进入编辑模式：填充表单，切换到快速接入 tab。 */
export function beginEdit(state: McpState, actions: UiActions, server: McpServerListEntry): void {
  state.editingName = server.name;
  state.editing = server;
  actions.switchTab("quick");
  fillForm(state, server);
  if (state.formScope !== undefined && (server.scope === "project" || server.scope === "global")) {
    state.formScope.value = server.scope;
  }
  const title = document.getElementById("dm-form-title");
  if (title !== null) title.textContent = t("editServer", { name: server.name });
  const cancel = document.querySelector<HTMLButtonElement>("[data-dm-cancel]");
  if (cancel !== null) cancel.disabled = false;
}

/** 构建「快速接入」页面（表单 + JSON 导入）。 */
export function buildQuickAdd(state: McpState, actions: UiActions): HTMLElement {
  const page = el("div");

  // 表单
  const form = el("section", { class: "dm-section" });
  form.appendChild(el("h3", { id: "dm-form-title", text: t("addServer") }));
  state.formName = el("input", {
    id: "dm-f-name",
    placeholder: "context7",
    value: state.editing?.name ?? "",
  });
  state.formScope = el("select", { id: "dm-f-scope" });
  state.formScope!.appendChild(el("option", { value: "project", text: t("scopeProjectOpt") }));
  state.formScope!.appendChild(el("option", { value: "global", text: t("scopeGlobalOpt") }));
  state.formScope!.value =
    state.editing?.scope ??
    (state.projectRoot !== undefined && state.projectRoot !== "" ? "project" : "global");
  state.formTransport = el("select", { id: "dm-f-transport" });
  state.formTransport!.appendChild(el("option", { value: "stdio", text: t("transportStdioOpt") }));
  state.formTransport!.appendChild(
    el("option", { value: "streamable-http", text: t("transportHttpOpt") }),
  );
  state.formCommand = el("input", { id: "dm-f-command", placeholder: "npx" });
  state.formArgs = el("input", { id: "dm-f-args", placeholder: "-y, @context7/mcp-server" });
  state.formEnv = el("textarea", { id: "dm-f-env", placeholder: t("envPlaceholder") });
  state.formCwd = el("input", { id: "dm-f-cwd", placeholder: t("cwdPlaceholder") });
  state.formUrl = el("input", { id: "dm-f-url", placeholder: "https://mcp.context7.com/mcp" });
  state.formHeaders = el("textarea", { id: "dm-f-headers", placeholder: t("headersPlaceholder") });
  state.formEnabled = el("input", { id: "dm-f-enabled", type: "checkbox", checked: true });

  const grid = el("div", { class: "dm-form" });
  grid.appendChild(
    el("div", {
      class: "dm-field",
      children: [el("label", { text: t("nameLabel") }), state.formName],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field",
      children: [el("label", { text: t("ownershipLabel") }), state.formScope],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field",
      children: [el("label", { text: t("transportLabel") }), state.formTransport],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field dm-full",
      children: [el("label", { text: t("commandLabel") }), state.formCommand],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field dm-full",
      children: [el("label", { text: t("argsLabel") }), state.formArgs],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field dm-full",
      children: [el("label", { text: t("envLabel") }), state.formEnv],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field dm-full",
      children: [el("label", { text: t("cwdLabel") }), state.formCwd],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field dm-full",
      children: [el("label", { text: t("urlLabel") }), state.formUrl],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-field dm-full",
      children: [el("label", { text: t("headersLabel") }), state.formHeaders],
    }),
  );
  grid.appendChild(
    el("div", {
      class: "dm-check dm-field dm-full",
      children: [state.formEnabled, el("label", { text: t("enabledLabel") })],
    }),
  );
  const actionsEl = el("div", { class: "dm-form-actions" });
  const save = el("button", {
    class: "dm-primary",
    text: t("save"),
    onclick: () => void saveForm(state, actions),
  });
  const cancel = el("button", {
    text: t("cancelEdit"),
    onclick: () => resetForm(state),
    disabled: true,
  });
  cancel.dataset.dmCancel = "";
  actionsEl.appendChild(save);
  actionsEl.appendChild(cancel);
  grid.appendChild(actionsEl);
  form.appendChild(grid);
  page.appendChild(form);

  // 传输类型切换显示/隐藏
  const syncTransport = () => {
    const isHttp = state.formTransport!.value === "streamable-http";
    for (const field of [state.formCommand, state.formArgs, state.formEnv, state.formCwd]) {
      (field!.closest(".dm-field") as HTMLElement).style.display = isHttp ? "none" : "flex";
    }
    for (const field of [state.formUrl, state.formHeaders]) {
      (field!.closest(".dm-field") as HTMLElement).style.display = isHttp ? "flex" : "none";
    }
  };
  state.formTransport!.addEventListener("change", syncTransport);

  // 粘贴 JSON 导入
  const paste = el("section", { class: "dm-section" });
  paste.appendChild(el("h3", { text: t("pasteTitle") }));
  const pasteBox = el("div", { class: "dm-paste-box" });
  const textarea = el("textarea", {
    class: "dm-full",
    placeholder:
      '{"my-server":{"command":"npx","args":["-y","pkg"],"env":{"KEY":"value"}},"remote":{"url":"https://...","headers":{}}}',
    style:
      "width:100%;min-height:90px;border:1px solid #d7dae0;border-radius:6px;padding:6px 8px;font-size:12px;font-family:ui-monospace,Consolas,monospace;box-sizing:border-box",
  });
  pasteBox.appendChild(textarea);
  pasteBox.appendChild(
    el("div", {
      class: "dm-actions",
      children: [
        el("button", {
          class: "dm-primary",
          text: t("importJson"),
          onclick: async () => {
            const result = pasteBox.querySelector(".dm-result")!;
            try {
              const payload = await api<{ imported: string[]; skipped: string[] }>(
                state.API.importJson,
                {
                  method: "POST",
                  headers: { "content-type": "application/json" },
                  body: JSON.stringify({
                    json: textarea.value,
                    scope: formScopeValue(state),
                    ...currentCwdBody(state),
                  }),
                },
              );
              result.textContent = t("importedOk", {
                names: payload.imported.join(", ") || t("importedNone"),
              });
              if (payload.skipped.length > 0) {
                result.appendChild(
                  el("div", {
                    class: "dm-skip",
                    text: t("importSkipped", { names: payload.skipped.join(", ") }),
                  }),
                );
              }
              await actions.refresh();
            } catch (error) {
              result.textContent = t("importFail", {
                msg: error instanceof Error ? error.message : String(error),
              });
            }
          },
        }),
      ],
    }),
  );
  pasteBox.appendChild(el("div", { class: "dm-result" }));
  paste.appendChild(pasteBox);
  page.appendChild(paste);

  return page;
}

/**
 * dsh-mcp-manager — 客户端「服务器列表页」渲染。
 *
 * 按状态分级展示服务器卡片（端点 / 错误 / 工具列表 / 操作按钮）。
 * 跨模块动作（refresh / resetForm / beginEdit）经 actions 注入，不直接引用
 * panel/quick-add 模块，避免循环依赖。
 */

import { el, pangu } from "../core/dom.ts";
import { api, toolDisableServerKey, cwdQueryOf } from "../core/api.ts";
import { STATUS_ORDER } from "../core/constants.ts";
import { tStatus } from "../core/i18n.ts";
import { t } from "../../../../../shared/client/i18n.js";
import type { McpServerListEntry, McpState, UiActions } from "../core/state.ts";

/** 服务器端点摘要：streamable-http 显示 URL，stdio 显示 command + args。 */
export function endpointOf(server: McpServerListEntry): string {
  if (server.transport === "streamable-http") return server.url ?? "";
  const args =
    Array.isArray(server.args) && server.args.length > 0 ? ` ${server.args.join(" ")}` : "";
  return `${server.command ?? ""}${args}`;
}

/** 操作按钮（统一失败提示）。 */
export function actionButton(
  label: string,
  onClick: () => void | Promise<void>,
  primary = false,
  danger = false,
): HTMLElement {
  return el("button", {
    class: `${primary ? "dm-primary" : ""} ${danger ? "dm-danger" : ""}`.trim(),
    text: label,
    onclick: async () => {
      try {
        await onClick();
      } catch (error) {
        window.alert(
          t("actionFail", { msg: error instanceof Error ? error.message : String(error) }),
        );
      }
    },
  });
}

/** 工具级禁用 checkbox（PATCH /api/dsh-mcp/tool-disable；#362 交互拍板 2b）。 */
function toolCheckbox(
  server: McpServerListEntry,
  tool: string,
  disabled: boolean,
  state: McpState,
  actions: UiActions,
): HTMLElement {
  const label = el("label", { class: "dm-tool" });
  const input = el("input", { type: "checkbox", checked: disabled });
  input.addEventListener("change", () => {
    // C6：全名形态经 toolDisableServerKey 归一，projectRoot 缺失时跳过提交
    // （防御非法 @/name，与浮窗 toolCheckbox 同口径）。
    const serverKey = toolDisableServerKey(server, state);
    if (serverKey === undefined) {
      input.checked = !input.checked;
      console.warn("[dsh-mcp-manager] projectRoot 缺失，跳过 tool-disable（非法 @/name 防御）");
      return;
    }
    void api<unknown>(state.API.toolDisable, {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        server: serverKey,
        tool,
        disabled: input.checked,
      }),
    })
      .then(() => actions.refresh())
      .catch((error: unknown) => {
        input.checked = !input.checked;
        console.warn("[dsh-mcp-manager] tool-disable failed:", error);
      });
  });
  label.appendChild(input);
  label.appendChild(document.createTextNode(tool));
  return label;
}

/** 工具折叠组：interactive 出 checkbox（可逐个禁用），否则出纯文本工具名。 */
export function serverToolsDetails(
  server: McpServerListEntry,
  toolCount: number,
  opts: { tools: boolean; openTools?: Set<string> },
  state: McpState,
  actions: UiActions,
  interactive: boolean,
): HTMLElement {
  const details = el("details", { class: "dm-tools", dataset: { dmServer: server.name } });
  if (opts.openTools?.has(server.name) === true) details.open = true;
  details.appendChild(el("summary", { text: t("toolsCount", { n: toolCount }) }));
  const list = el("ul");
  const tools = Array.isArray(server.tools) ? server.tools : [];
  if (interactive) {
    const disabledSet = new Set(Array.isArray(server.disabledTools) ? server.disabledTools : []);
    for (const tool of tools) {
      list.appendChild(
        el("li", {}, [toolCheckbox(server, tool, disabledSet.has(tool), state, actions)]),
      );
    }
  } else {
    for (const tool of tools) list.appendChild(el("li", { text: tool }));
  }
  details.appendChild(list);
  return details;
}

/** 一个操作按钮的规格（label / 主按钮样式 / 执行体）。 */
interface ActionSpec {
  label: string;
  primary: boolean;
  danger?: boolean;
  run: () => void | Promise<void>;
}

/** JSON 写请求 init（PATCH enabled 用；形态与 quick-add 同款）。 */
export function jsonPatchInit(enabled: boolean): {
  method: "PATCH";
  headers: Record<string, string>;
  body: string;
} {
  return {
    method: "PATCH",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ enabled }),
  };
}

/** POST 后刷新（连接/断开/重连三个动作的执行体同式）。 */
export function postThenRefresh(
  state: McpState,
  actions: UiActions,
  url: string,
): () => Promise<void> {
  return async () => {
    await api<unknown>(url, { method: "POST" });
    await actions.refresh();
  };
}

/** 状态动作：connected → 断开 + 重连；disabled → 启用并连接；其余 → 连接。 */
export function statusActions(
  server: McpServerListEntry,
  state: McpState,
  actions: UiActions,
  scopeQuery: string,
  cwdQuery: string,
): ActionSpec[] {
  const name = encodeURIComponent(server.name);
  if (server.status === "connected") {
    return [
      {
        label: t("disconnect"),
        primary: false,
        run: postThenRefresh(
          state,
          actions,
          `${state.API.disconnect}?name=${name}${scopeQuery}${cwdQuery}`,
        ),
      },
      {
        label: t("reconnect"),
        primary: false,
        run: postThenRefresh(
          state,
          actions,
          `${state.API.reconnect}?name=${name}${scopeQuery}${cwdQuery}`,
        ),
      },
    ];
  }
  if (server.status === "disabled") {
    return [
      {
        label: t("enableAndConnect"),
        primary: true,
        run: async () => {
          await api<unknown>(`${state.API.servers}?name=${name}${scopeQuery}`, jsonPatchInit(true));
          await api<unknown>(`${state.API.connect}?name=${name}${scopeQuery}${cwdQuery}`, {
            method: "POST",
          });
          await actions.refresh();
        },
      },
    ];
  }
  return [
    {
      label: t("connect"),
      primary: true,
      run: postThenRefresh(
        state,
        actions,
        `${state.API.connect}?name=${name}${scopeQuery}${cwdQuery}`,
      ),
    },
  ];
}

/** 禁用动作（非 disabled 行才有）：PATCH 后若正在编辑该条目则重置表单。 */
export function disableAction(
  server: McpServerListEntry,
  state: McpState,
  actions: UiActions,
  scopeQuery: string,
  cwdQuery: string,
): ActionSpec {
  const name = encodeURIComponent(server.name);
  return {
    label: t("disable"),
    primary: false,
    run: async () => {
      // C7：disable 带 cwd（与 disconnect 对齐，#412 会话自愈）。
      await api<unknown>(
        `${state.API.servers}?name=${name}${scopeQuery}${cwdQuery}`,
        jsonPatchInit(false),
      );
      if (state.editingName === server.name) actions.resetForm();
      await actions.refresh();
    },
  };
}

/** 删除动作：先确认（未确认即中止），DELETE 后若正在编辑该条目则重置表单。 */
export function deleteAction(
  server: McpServerListEntry,
  state: McpState,
  actions: UiActions,
  scopeQuery: string,
): ActionSpec {
  const name = encodeURIComponent(server.name);
  return {
    label: t("delete"),
    primary: false,
    danger: true,
    run: async () => {
      if (!window.confirm(t("confirmDelete", { name: server.name }))) return;
      await api<unknown>(`${state.API.servers}?name=${name}${scopeQuery}`, { method: "DELETE" });
      if (state.editingName === server.name) actions.resetForm();
      await actions.refresh();
    },
  };
}

/** 需要置顶提醒的服务器（失败 + 重连中）。 */
export function needsAttention(server: McpServerListEntry): boolean {
  return server.status === "failed" || server.status === "reconnecting";
}

/** 按状态分桶（桶序 = STATUS_ORDER；未知状态归 stopped 桶，不丢行）。 */
export function bucketByStatus(list: McpServerListEntry[]): Map<string, McpServerListEntry[]> {
  const byStatus = new Map<string, McpServerListEntry[]>();
  for (const group of STATUS_ORDER) byStatus.set(group.key, []);
  for (const server of list) {
    const bucket = byStatus.get(server.status) ?? byStatus.get("stopped");
    if (bucket !== undefined) bucket.push(server);
  }
  return byStatus;
}
/** 卡片根类名：失败 / 重连中加 --fail 修饰。 */
export function serverCardClass(server: McpServerListEntry): string {
  return needsAttention(server) ? "dm-server dm-server--fail" : "dm-server";
}

/** 卡片头部：名称 / transport 徽标 / scope 徽标 / 状态徽标 / 工具计数。 */
export function serverCardHeader(server: McpServerListEntry, toolCount: number): HTMLElement {
  const isHttp = server.transport === "streamable-http";
  const header = el("header");
  header.appendChild(el("span", { class: "dm-name", text: server.name }));
  header.appendChild(
    el("span", {
      class: `dm-badge ${isHttp ? "dm-http" : "dm-stdio"}`,
      text: isHttp ? "HTTP" : "stdio",
    }),
  );
  header.appendChild(
    el("span", {
      class: "dm-badge",
      text: server.scope === "project" ? t("badgeScopeProject") : t("badgeScopeGlobal"),
    }),
  );
  header.appendChild(
    el("span", { class: `dm-badge dm-st-${server.status}`, text: tStatus(server.status) }),
  );
  header.appendChild(
    el("span", { class: "dm-count", text: t("toolsCountPlain", { n: toolCount }) }),
  );
  return header;
}

/** 渲染单台服务器卡片。 */
export function renderServer(
  server: McpServerListEntry,
  state: McpState,
  actions: UiActions,
  opts: { tools: boolean; openTools?: Set<string> } = { tools: true },
): HTMLElement {
  const article = el("article", { class: serverCardClass(server) });
  const toolCount = Array.isArray(server.tools) ? server.tools.length : 0;
  article.appendChild(serverCardHeader(server, toolCount));

  article.appendChild(el("div", { class: "dm-endpoint", text: endpointOf(server) }));
  if (server.error !== undefined && server.error !== "") {
    article.appendChild(el("div", { class: "dm-err", text: server.error }));
  }

  if (toolCount > 0) {
    article.appendChild(serverToolsDetails(server, toolCount, opts, state, actions, opts.tools));
  }

  const actionsEl = el("div", { class: "dm-actions" });
  const busy = server.status === "connecting" || server.status === "reconnecting";
  const scopeQuery = `&scope=${server.scope}`;
  // #412 复报：宿主 dsh web 重启后 projectRoot 丢失，connect/reconnect 路由的
  // maybeSession 需 cwd 才能恢复会话（否则 connect(scope=project) 抛
  // "no active project session"）。带上当前会话 cwd，宿主 setSession 幂等短路，
  // 正常时零副作用。
  const cwdQuery = cwdQueryOf(state);
  // C7：disconnect / connect / disable 同样带 cwd（#412 场景浮窗/面板操作自愈）。
  for (const spec of statusActions(server, state, actions, scopeQuery, cwdQuery)) {
    actionsEl.appendChild(actionButton(spec.label, spec.run, spec.primary));
  }
  // 禁用开关：非 disabled 状态可一键禁用（宿主断开并注销工具）
  if (server.status !== "disabled") {
    const disable = disableAction(server, state, actions, scopeQuery, cwdQuery);
    actionsEl.appendChild(actionButton(disable.label, disable.run, disable.primary));
  }
  actionsEl.appendChild(actionButton(t("edit"), () => actions.beginEdit(server)));
  const remove = deleteAction(server, state, actions, scopeQuery);
  actionsEl.appendChild(
    actionButton(remove.label, remove.run, remove.primary, remove.danger === true),
  );
  (actionsEl.children[actionsEl.children.length - 1] as HTMLButtonElement).disabled = busy;
  article.appendChild(actionsEl);
  return article;
}

/** 渲染服务器列表页（#362 交互拍板 1a：项目级 / 全局级两大分组，各自内部再按状态）。
 * 单池（#767）后两大分组的服务器都经中间层，工具 checkbox 一律可用。 */
export function renderServers(state: McpState, actions: UiActions): void {
  if (state.bodyEl === undefined) return;
  // C8：checkbox 操作后 actions.refresh 全量重建会丢 <details> 折叠态——渲染
  // 前收集当前展开的工具组（按 server 名），重建后恢复（连续禁用 N 个工具
  // 免反复展开）。
  const openTools = new Set<string>();
  for (const d of state.bodyEl.querySelectorAll<HTMLDetailsElement>("details.dm-tools")) {
    if (d.open && d.dataset.dmServer !== undefined) openTools.add(d.dataset.dmServer);
  }
  state.bodyEl.textContent = "";
  if (state.servers.length === 0) {
    state.bodyEl.appendChild(
      el("div", { class: "dm-status", children: [document.createTextNode(t("serversEmpty"))] }),
    );
    return;
  }
  // 失败优先：需关注组置顶（跨 scope），其余再按 project/global × 状态。
  const attention = state.servers.filter(needsAttention);
  const rest = state.servers.filter((server: McpServerListEntry) => !needsAttention(server));
  const appendGroup = (title: string, list: McpServerListEntry[], alert: boolean): void => {
    if (list.length === 0) return;
    const section = el("section", { class: "dm-group" });
    // class 键省略（勿传 undefined，否则 className="undefined"）
    const titleEl = alert ? el("h3", { class: "dm-group-alert" }) : el("h3");
    titleEl.appendChild(document.createTextNode(title));
    section.appendChild(titleEl);
    const byStatus = bucketByStatus(list);
    for (const group of STATUS_ORDER) {
      const bucket = byStatus.get(group.key) ?? [];
      if (bucket.length === 0) continue;
      const sub = el("div", { class: "dm-subgroup" });
      sub.appendChild(
        el("h4", {
          class: "dm-subgroup-title",
          text: pangu(t("statusGroupCount", { status: t(group.titleKey), n: bucket.length })),
        }),
      );
      for (const server of [...bucket].sort((a: McpServerListEntry, b: McpServerListEntry) =>
        a.name.localeCompare(b.name),
      )) {
        sub.appendChild(renderServer(server, state, actions, { tools: true, openTools }));
      }
      section.appendChild(sub);
    }
    state.bodyEl!.appendChild(section);
  };
  appendGroup(t("groupAttention", { n: attention.length }), attention, true);
  for (const scope of ["project", "global"]) {
    const list = rest.filter((server: McpServerListEntry) => server.scope === scope);
    if (list.length === 0) continue;
    // 标题自带数量，不再额外挂 dm-count（避免双计数）；字面量已带空格，
    // 不经 pangu（计数拼装与盘古分层，避免语义错层）。
    const label = scope === "project" ? t("groupProject") : t("groupGlobal");
    appendGroup(`${label} (${list.length})`, list, false);
  }
}

