/**
 * dsh-mcp-manager — 客户端 HTTP API 请求与请求参数拼装（core 层）。
 *
 * 阶段 7 分层：本文件拆出自原 dom.ts（dom.ts 保留 DOM 工具职责 el()，
 * HTTP 请求职责独立成 api.ts），与宿主 ROUTES 的对接面收拢一处。
 * 仅 export 纯函数，不依赖任何状态。
 */

import type { ApiRequestOptions, McpState, McpServerListEntry } from "./state.ts";

/**
 * tool-disable 的服务器全名形态（C6/C-DTO-4）：`@@global/<name>` 或
 * `@<绝对路径>/<name>`，与宿主 parseFullServerName 归一化一致；projectRoot
 * 缺失（宿主重启 #412）时返回 undefined——调用方必须跳过提交，不得拼非法
 * `@/name`（宿主 parseFullServerName slash<=1 会 400 拒绝）。
 */
export function toolDisableServerKey(
  server: McpServerListEntry,
  state: McpState,
): string | undefined {
  if (server.scope === "global") return `@@global/${server.name}`;
  const root = state.projectRoot;
  if (typeof root !== "string" || root === "") return undefined;
  return `@${root}/${server.name}`;
}

/**
 * 会话 cwd 查询参数（C7/#412 自愈）：connect/reconnect/disable 等操作携带
 * 当前会话 cwd，宿主 maybeSession 据此恢复会话（项目级连接需要；
 * 宿主 setSession 幂等短路，正常时零副作用）。空 cwd 返回空串。
 */
export function cwdQueryOf(state: McpState): string {
  return typeof state.currentCwd === "string" && state.currentCwd !== ""
    ? `&cwd=${encodeURIComponent(state.currentCwd)}`
    : "";
}

/**
 * HTTP API 请求。
 * 返回 JSON 解析后的 body；非 2xx 抛 Error。
 * 带默认超时（10s，AbortSignal），防挂起请求占用连接（#111 变更点驱动）。
 * 调用方自带 signal 时：超时兜底不启用（调用方 signal 优先，避免双取消竞争）。
 *
 * C14 备忘：当前全部路由返回 JSON body；未来新增 204 无 body 路由时，
 * response.json() 抛错会落到 body=undefined，调用方不得静默把 undefined
 * 当成功结果消费（需在新增 204 路由时显式补状态码分支）。
 */
export async function api<T = unknown>(path: string, options: ApiRequestOptions = {}): Promise<T> {
  const timeoutMs = options.timeoutMs ?? 10_000;
  const hasCallerSignal = options.signal !== undefined;
  const controller = new AbortController();
  const timer = hasCallerSignal
    ? undefined
    : setTimeout(
        () => controller.abort(new Error(`request timed out (${timeoutMs}ms)`)),
        timeoutMs,
      );
  const merged: ApiRequestOptions = { ...options, signal: options.signal ?? controller.signal };
  try {
    const response = await fetch(path, merged);
    let body: unknown;
    try {
      body = await response.json();
    } catch {
      body = undefined;
    }
    if (!response.ok) {
      const msg = (body as { error?: string } | undefined)?.error ?? `HTTP ${response.status}`;
      throw new Error(msg);
    }
    return body as T;
  } finally {
    if (timer !== undefined) clearTimeout(timer);
  }
}

/**
 * dsh-mcp-manager — 客户端常量与状态映射。
 *
 * 状态排序、状态点颜色、API 路径等纯常量，不依赖任何状态。
 * i18n（issue #348）：状态文案存字典 key（title/STATUS_TEXT），渲染期经 t 求值
 * （模块加载时 t 尚未装配，不能固化文案字符串）。
 *
 * 跨端契约（路径清单 / 六态状态键）的物理定义在 src/shared/，本文件只做客户端投影；
 * 展示顺序、CSS 颜色与字典 key 是纯展示数据，留在原处（D5 单一事实源判据）。
 */

import type { McpLocaleKey } from "../locales.ts";
import { ROUTES, SERVER_STATES } from "../../shared/interface.ts";

/** 路径表：逐键取宿主同一份 ROUTES（一致性锁 test/e2e/cross-end-lock.test.ts 盯这条）。 */
export const API = {
  servers: ROUTES.servers,
  connect: ROUTES.connect,
  disconnect: ROUTES.disconnect,
  reconnect: ROUTES.reconnect,
  importJson: ROUTES.importJson,
  session: ROUTES.session,
  resume: ROUTES.resume,
  config: ROUTES.config,
  events: ROUTES.events,
  health: ROUTES.health,
  toolDisable: ROUTES.toolDisable,
};

/** 状态分组排序（按优先级降序；titleKey 为字典 key，渲染期 t(titleKey)）。 */
export const STATUS_ORDER = [
  {
    key: SERVER_STATES.connected,
    titleKey: "stConnected" as McpLocaleKey,
    dot: "var(--dsw-alias-state-success-primary,#0f9d6e)",
  },
  {
    key: SERVER_STATES.connecting,
    titleKey: "stConnecting" as McpLocaleKey,
    dot: "var(--dsw-alias-state-business-primary,#2f7bf6)",
  },
  {
    key: SERVER_STATES.reconnecting,
    titleKey: "stReconnecting" as McpLocaleKey,
    dot: "var(--dsw-alias-state-warn-primary,#e08b1e)",
  },
  {
    key: SERVER_STATES.stopped,
    titleKey: "stStopped" as McpLocaleKey,
    dot: "var(--dsw-alias-label-tertiary,#9aa1ad)",
  },
  {
    key: SERVER_STATES.disabled,
    titleKey: "stDisabled" as McpLocaleKey,
    dot: "var(--dsw-alias-label-tertiary,#9aa1ad)",
  },
  {
    key: SERVER_STATES.failed,
    titleKey: "stFailed" as McpLocaleKey,
    dot: "var(--dsw-alias-state-error-primary,#e0483e)",
  },
];

/** 状态 → 字典 key 映射（渲染期 t(STATUS_TEXT[status])；未知状态回落原始 key 显示）。 */
export const STATUS_TEXT: Record<string, McpLocaleKey> = {
  [SERVER_STATES.connected]: "stConnected",
  [SERVER_STATES.connecting]: "stConnecting",
  [SERVER_STATES.reconnecting]: "stReconnecting",
  [SERVER_STATES.stopped]: "stStopped",
  [SERVER_STATES.disabled]: "stDisabled",
  [SERVER_STATES.failed]: "stFailed",
};

/** 状态点颜色（与 STATUS_ORDER 一致）。 */
export function statusDot(status: string): string {
  const group = STATUS_ORDER.find((entry) => entry.key === status);
  return group !== undefined ? group.dot : "var(--dsw-alias-label-tertiary,#9aa1ad)";
}

/**
 * dsh-mcp-manager — 客户端 DOM 工具函数（core 层）。
 *
 * 阶段 7 分层：HTTP API 请求已拆出至 ./api.ts（拆出自原 dom.ts——dom.ts
 * 保留 DOM 元素创建职责，api.ts 收 HTTP 请求职责）。
 * 仅 export 纯函数，不依赖任何状态。
 */

/** el() 的 attrs 是结构化属性袋：checked/disabled 只落在能接收它们的表单控件上。 */
type FormControl = HTMLInputElement | HTMLButtonElement | HTMLSelectElement | HTMLTextAreaElement;

/**
 * 盘古之白：CJK 与拉丁字母/数字之间自动插入半角空格。
 * 用于状态摘要等中英混排文案（不要对纯标识符/服务器名调用）。
 * 覆盖面说明：仅 CJK 统一表意文字（U+3400–U+4DBF、U+4E00–U+9FFF）与兼容区
 * （U+F900–U+FAFF），假名/谚文/扩展 B+ 不在范围内——状态文案均为中文标点+
 * 拉丁数字/括号，该范围已够用；如需扩面先补单测再放宽。
 * 连字符说明：类内不得出现裸 `-`（旧写法 `㐀-鿿-鿿` 被解析为字面连字符，
 * 会把 `project-1` 撕成 `project- 1`——连字符标识符必须保持原样）。
 */
export function pangu(text: string): string {
  return String(text)
    .replace(/([㐀-䶿一-鿿豈-﫿])([A-Za-z0-9@#$%^&*()[\]{}<>+\-=/\\|])/g, "$1 $2")
    .replace(/([A-Za-z0-9@#$%^&*()[\]{}<>+\-=/\\|])([㐀-䶿一-鿿豈-﫿])/g, "$1 $2");
}

/**
 * 逐条把属性袋落到元素上：回答「这个键该走哪条属性通道？」——
 * class/text/dataset/事件/表单布尔各有专属通道，其余一律 setAttribute。
 * 与「子节点怎么挂」是两种变化原因，故分块；判定顺序与通道归属逐条照旧。
 */
function applyAttrs(node: HTMLElement, attrs: Record<string, unknown>): void {
  for (const [key, value] of Object.entries(attrs)) {
    if (key === "class") node.className = value == null ? "" : String(value);
    else if (key === "text") node.textContent = String(value);
    else if (key === "dataset") Object.assign(node.dataset, value as Record<string, string>);
    else if (key.startsWith("on")) node.addEventListener(key.slice(2), value as EventListener);
    else if (key === "checked") (node as HTMLInputElement).checked = value as boolean;
    else if (key === "disabled") (node as FormControl).disabled = value as boolean;
    else if (key === "children") continue;
    else node.setAttribute(key, String(value));
  }
}

/** 把子节点值挂到元素下：字符串建文本节点，null/undefined 跳过，其余按 Node 直挂。 */
function appendKids(node: Node, kids: readonly unknown[]): void {
  for (const child of kids) {
    if (child === undefined || child === null) continue;
    node.appendChild(typeof child === "string" ? document.createTextNode(child) : (child as Node));
  }
}

/** 创建带属性/子节点的 DOM 元素（泛型按标签名收窄返回）。 */
export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, unknown> = {},
  children?: unknown[],
): HTMLElementTagNameMap[K] {
  // children 兼容两种传法：第三个位置参数，或 attrs.children（本插件调用点
  // 一直把 children 放进 attrs——早期版本只读第三参数导致子节点从未挂载）。
  const kids: unknown[] = children ?? (attrs.children as unknown[] | undefined) ?? [];
  const node = document.createElement(tag);
  applyAttrs(node, attrs);
  appendKids(node, kids);
  return node;
}

/**
 * dsh-mcp-manager — 客户端状态类型与工厂。
 *
 * 所有可变状态收进单一 McpState 对象，在 apply() 内创建，经参数传递到各模块。
 * 禁止模块级全局变量，确保连续挂载/卸载无残留。
 *
 * 跨端 DTO 形状（服务器列表条目 / 浮窗 UI 配置）的物理定义在 src/shared/dto.ts
 * （D5）：这里只做薄 re-export，客户端不得自带等值副本——一致性锁
 * test/e2e/cross-end-lock.test.ts 与 test/integration/service-contract.test.ts 盯这条。
 */

import { API } from "./constants.ts";
import { DEFAULT_Z_INDEX_BASE } from "../../shared/interface.ts";
import type { ClientUiConfig, McpServerListEntry, ServerState } from "../../shared/interface.ts";
import type { ISessions } from "@deepseek-ai/dsh-api-session-controller/client";
import type { LocaleRuntime } from "@deepseek-ai/dsh-client-locale/client";
import type { SlotRegistry } from "@deepseek-ai/dsh-client-ui-renderer/client";

export type { ClientUiConfig, McpServerListEntry } from "../../shared/interface.ts";

/** 各状态计数（六态键的物理定义在 shared/status.ts，宿主与客户端同一份）。 */
export type McpCounts = Partial<Record<ServerState, number>>;

/** MCP 管理器客户端全部可变状态。 */
export interface McpState {
  /** 模态面板遮罩层根元素。 */
  overlay: HTMLElement | undefined;
  /** 模态面板卡片根元素。 */
  card: HTMLElement | undefined;
  /** 模态面板 body 容器。 */
  bodyEl: HTMLElement | undefined;
  /** 模态面板是否打开。 */
  open: boolean;
  /** 打开面板时的焦点归属（R6 关还焦：close 时恢复；非元素/已卸载则跳过）。 */
  panelOpener: HTMLElement | undefined;
  /** 当前激活的 tab（servers / quick）。 */
  activeTab: string;
  /** 服务器列表。 */
  servers: McpServerListEntry[];
  /** 各状态计数。 */
  counts: McpCounts;
  /** 正在编辑的服务器名称（undefined 表示新建）。 */
  editingName: string | undefined;
  /** 正在编辑的服务器原始数据。 */
  editing: McpServerListEntry | undefined;

  // 表单 DOM 引用
  formName: HTMLInputElement | undefined;
  formScope: HTMLSelectElement | undefined;
  formTransport: HTMLSelectElement | undefined;
  formCommand: HTMLInputElement | undefined;
  formArgs: HTMLInputElement | undefined;
  formEnv: HTMLTextAreaElement | undefined;
  formCwd: HTMLInputElement | undefined;
  formUrl: HTMLInputElement | undefined;
  formHeaders: HTMLTextAreaElement | undefined;
  formEnabled: HTMLInputElement | undefined;

  // 浮窗状态
  floatPill: HTMLElement | undefined;
  floatPanel: HTMLElement | undefined;
  floatOpen: boolean;
  currentCwd: string | undefined;
  /**
   * 是否已解析出当前会话（#1028）。false = **未知**，与「已知但无 cwd」是两态：
   * 未知时不得向宿主上报 `cwd:""`，否则会把「读不到」变成「清空项目级绑定」。
   */
  sessionResolved: boolean;
  /** 未知态的一次性告警闸（可观测性：未知态无 UI 表现，不告警等于静默失效）。 */
  warnedUnknownSession: boolean;
  /**
   * 连续未知帧计数（#1028 告警口径）。官方会话快照要等 mainView 持有才就绪，
   * 故**首帧未知是竞态不是故障**（每次冷启动必现）；用它把噪声与真失联分开。
   */
  unknownSessionFrames: number;
  projectRoot: string | undefined;
  updateFloatState: (() => void) | undefined;
  mcpUiConfig: ClientUiConfig;

  // 路径表（单一来源 src/shared/routes.ts，经 client/core/constants.ts 投影）。
  API: typeof API;
}

/** 创建初始状态对象。 */
export function createState(): McpState {
  return {
    overlay: undefined,
    card: undefined,
    bodyEl: undefined,
    open: false,
    panelOpener: undefined,
    activeTab: "servers",
    servers: [],
    counts: {},
    editingName: undefined,
    editing: undefined,
    formName: undefined,
    formScope: undefined,
    formTransport: undefined,
    formCommand: undefined,
    formArgs: undefined,
    formEnv: undefined,
    formCwd: undefined,
    formUrl: undefined,
    formHeaders: undefined,
    formEnabled: undefined,
    floatPill: undefined,
    floatPanel: undefined,
    floatOpen: false,
    currentCwd: undefined,
    sessionResolved: false,
    warnedUnknownSession: false,
    unknownSessionFrames: 0,
    projectRoot: undefined,
    updateFloatState: undefined,
    mcpUiConfig: {
      position: "top-right",
      offsetX: 8,
      offsetY: 8,
      blankY: 40,
      zIndexBase: DEFAULT_Z_INDEX_BASE,
    },
    API: { ...API },
  };
}

/**
 * 跨模块动作回调集合。
 * index.ts 装配，避免 feature 模块间循环依赖——各模块通过 actions 调用
 * 其他模块的功能（如 servers.ts 调用 actions.refresh / actions.resetForm）。
 */
export interface UiActions {
  refresh: () => Promise<boolean>;
  resetForm: () => void;
  beginEdit: (server: McpServerListEntry) => void;
  switchTab: (tab: string) => void;
  close: () => void;
  showPanel: () => void;
  toggleFloat: (force?: boolean) => void;
}

/**
 * locale 服务最小面：官方 `LocaleRuntime`（dsh-client-locale，宿主 ctx.locale）的 Pick。
 * 成员一律必选——官方类上本就是必选方法，服务本体缺失由 `ctx.get("locale")` 的
 * `| undefined` 表达；index.ts 里既有的 typeof 守卫（H4）是运行时防御，原样保留。
 *
 * 官方形状对齐说明：官方 `register` 两个重载都返回 disposer `() => void`，本包调用点
 * **既成事实地丢弃**该返回值（只把 subscribe 的 unsub 存进 effect 卸载），此处仅把返回
 * 类型按官方补齐，**不新增任何清理/生命周期逻辑**。`getSnapshot` 官方必返 `LocaleSnapshot`，
 * 本包只在 typeof 守卫里探测成员存在，从不读返回值，故面里只带方法类型不带结果。
 */
export type McpLocaleService = Pick<
  LocaleRuntime,
  "register" | "subscribe" | "getSnapshot" | "bind"
>;

/**
 * slots 服务最小面：官方 `SlotRegistry`（dsh-client-ui-renderer，宿主 ctx.slots）的
 * inject/register Pick，与 index.ts 的行配置装配面同源同形。
 *
 * 官方形状对齐说明：官方 `inject(key, callback)` 与 `register(options, component)` **都**
 * 返回 disposer `() => void`；本类型此前把 inject 误写成返回 void（index.ts 的局部声明
 * 反而写对了），此处一律以官方为准。成员不再 optional：服务本体缺失已由
 * `ctx.get("slots")` 的 `| undefined` 表达，调用点本就先判空再调（G2 零行为改动）。
 */
export type McpSlotsService = Pick<SlotRegistry, "inject" | "register">;

/**
 * 客户端上下文最小面（S2：get 重载 + effect + sessions?；H6 不反向依赖未清洁形状）。
 * get("locale"/"slots")返回上两个官方派生面，未声明服务时为 undefined；其余名回落 unknown。
 */
export interface McpClientContext {
  get(name: "locale"): McpLocaleService | undefined;
  get(name: "slots"): McpSlotsService | undefined;
  get(name: string): unknown;
  effect: (fn: () => () => void, label?: string) => void;
  /**
   * 官方会话服务（#1028：不再自建镜像面——rc.2 的 `SessionListState` 已无 `current`，
   * 自建形状会与官方静默分叉）。未注入时为 undefined。
   */
  sessions?: ISessions;
}

/**
 * 客户端 HTTP 请求选项最小面（P3-b/B6：api 二选一选 A 泛型）。
 * 继承 DOM RequestInit（method/headers/body/signal），仅增 timeoutMs 兜底预算。
 */
export interface ApiRequestOptions extends RequestInit {
  timeoutMs?: number;
}

/**
 * dsh-mcp-manager — 客户端 i18n 渲染辅助（core 层）。
 *
 * 阶段 7 分层：本文件拆出自 locales.ts（字典数据与 McpLocaleKey 类型留在
 * 根目录 locales.ts 供 LocaleNamespaceMap 声明合并；渲染期文案求值辅助收
 * 到本文件，与状态映射 constants.ts 协作）。
 */

import { t } from "../../../../../shared/client/i18n.js";
import { STATUS_TEXT } from "./constants.ts";

/**
 * 状态文案求值：已知状态取字典翻译，未知状态回落原始 key 原样显示
 * （C13：未知状态按 stopped 投影、不丢卡——文案层同样不丢原文案）。
 */
export function tStatus(status: string): string {
  return STATUS_TEXT[status] !== undefined ? t(STATUS_TEXT[status]) : status;
}

