      editingName: "a",
      editing: entry({ name: "a", scope: "global", hasSecrets: false }),
    });
    const ok = await performSaveRequest(
      s,
      { name: "b", transport: "stdio" },
      { name: "b", scope: "global" },
    );
    expect(ok).toBe(true);
    expect(fetchFake.calls).toHaveLength(2);
